// Andreas Meyer in Malsch mit 10km Radius
return [{
  json: {
    id: 'test-kandidat',
    name: 'Andreas Meyer (TEST)',
    lat: 48.8794,
    lng: 8.3311,
    max_distanz_km: 10,
    type: 'kandidat'
  }
}, {
  json: {
    id: 'shop1',
    name: 'Malsch (0 km)',
    lat: 48.8794,
    lng: 8.3311,
    type: 'shop'
  }
}, {
  json: {
    id: 'shop2',
    name: 'Gaggenau (9.9 km)',
    lat: 48.8042,
    lng: 8.3250,
    type: 'shop'
  }
}, {
  json: {
    id: 'shop3',
    name: 'Karlsruhe (20 km - ZU WEIT)',
    lat: 49.0069,
    lng: 8.4037,
    type: 'shop'
  }
}];

const all = $input.first().json.data;
const kandidaten = all.filter(x => x.type === 'kandidat');
const shops = all.filter(x => x.type === 'shop');

function distance(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = (lat2-lat1) * Math.PI/180;
  const dLon = (lon2-lon1) * Math.PI/180;
  const a = Math.sin(dLat/2)**2 + Math.cos(lat1*Math.PI/180) * Math.cos(lat2*Math.PI/180) * Math.sin(dLon/2)**2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const results = [];

for (const k of kandidaten) {
  const maxDist = Number(k.max_distanz_km);
  if (!maxDist || isNaN(maxDist)) continue;

  const allShopsDebug = [];
  const nearby = [];

  for (const s of shops) {
    const d = distance(k.lat, k.lng, s.lat, s.lng);
    const distKm = Math.round(d*10)/10;

    allShopsDebug.push({
      name: s.name,
      distanz: distKm,
      max_erlaubt: maxDist,
      passt: d <= maxDist ? 'JA ✓' : 'NEIN ✗'
    });

    if (d <= maxDist) {
      nearby.push({ id: s.id, name: s.name, dist: distKm });
    }
  }

  nearby.sort((a,b) => a.dist - b.dist);

  results.push({
    json: {
      kandidat: k.name,
      max_distanz: maxDist + ' km',
      alle_shops_debug: allShopsDebug,
      zugeordnet: nearby.length,
      shops_namen: nearby.map(x => x.name + ' (' + x.dist + ' km)').join(', ')
    }
  });
}

return results;
